    {
      "path": "src/index.ts",
      "content": "/**\n * dsh-redstone-music —— 把\"制作 Minecraft 红石音乐\"的全套能力做成 DSH 插件\n *\n * 装上它，任何会话都能：\n *   ① 查这一整套流程里【踩过的所有坑】（12 条硬教训，含症状/根因/修法/检测命令）\n *   ② 按固定 9 步流程做一条带子\n *\n * 已实现：redstone_music_pitfalls / redstone_music_pipeline / rm_render / rm_build\n * 规划中（见 src/knowledge.ts 的 PIPELINE）：\n *   rm_analyze / rm_plan / rm_pack / rm_verify / rm_fx\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { Config } from './config'\nimport type { Config as ConfigShape } from './config'\nimport { applyTools } from './tools'\n\nexport const name = 'dsh-redstone-music'\nexport const inject = ['tools']\n\n// Re-export the schema so the loader can validate this plugin's config.\nexport { Config }\n\n// Every registration is an effect: `ctx.tools.register` returns the disposer that\n// removes the tool on unload, so the plugin stays hot-reloadable (guide §3.3).\nexport function apply(ctx: Context, config: ConfigShape): void {\n  if (config.enabled === false) return\n  applyTools(ctx, config)\n}\n"
    },
    {
      "path": "src/tool-build.ts",
      "content": "/**\n * tool-build.ts —— rm_build：谱面 + 轨表 → 数据包（mcfunction 分片）→ 可选部署并开建\n *\n * 对应 PIPELINE 第 7/8 步。两条硬教训直接写进实现：\n *   · `mcfunction-batch`：命令收集起来写成 .mcfunction（每片 8000 条，片间 schedule 2t），\n *     而不是逐格 RCON —— 实测 143,712 条命令 30 秒跑完，逐格要 40 分钟；\n *   · `delay-compensation`：内容按【全局单位】摆（x = originX + 2u + 1），\n *     各轨链条起点 xStart = originX + 2·delay，否则整条轨晚 delay 个单位。\n */\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Config } from './config'\nimport {\n  DEFAULT_GEOMETRY,\n  type GeometryOptions,\n  type LaneSpec,\n} from './music/lane-layout'\nimport { planBuild, type BuildProject } from './music/build'\nimport { writeDatapack } from './music/datapack'\nimport { forceloadCommands, forceloadSegments } from './music/commands'\nimport { openRcon } from './music/rcon'\nimport type { SongNote, SongPlan } from './music/score'\n\ninterface RawLane {\n  label?: string\n  instrument?: string\n  block?: string\n  side?: string\n  pos?: number\n  window?: number[] | null\n  sample?: number\n  tracks?: number[]\n  keys?: number[]\n  keyBlocks?: unknown\n  tune?: number\n  thin?: number\n  mirrorOf?: string\n}\n\ninterface RawGeometry {\n  originX?: number\n  baseY?: number\n  walkMid?: number\n  laneGap?: number\n  tailUnits?: number\n  busRefreshInterval?: number\n}\n\n/** 把 JSON 里的 keyBlocks 收敛成\"鼓键 → 方块\"字符串映射 */\nexport function toKeyBlocks(raw: unknown, at: string, problems: string[]): Record<string, string> | undefined {\n  if (raw === undefined || raw === null) return undefined\n  if (typeof raw !== 'object' || Array.isArray(raw)) {\n    problems.push(`${at}.keyBlocks 必须是 { \"鼓键\": \"方块\" } 形式的对象`)\n    return undefined\n  }\n  const out: Record<string, string> = {}\n  for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {\n    if (!/^\\d+$/.test(key)) problems.push(`${at}.keyBlocks 的键 \"${key}\" 不是鼓键号`)\n    else if (typeof value !== 'string') problems.push(`${at}.keyBlocks[\"${key}\"] 必须是方块 id 字符串`)\n    else out[key] = value\n  }\n  return out\n}\n\nexport function toLanes(raw: readonly RawLane[]): LaneSpec[] {\n  const problems: string[] = []\n  const lanes = raw.map((lane, index) => {\n    const at = `lanes[${index}]${lane.label ? `(${lane.label})` : ''}`\n    if (!lane.label) problems.push(`${at} 缺 label`)\n    if (!lane.instrument) problems.push(`${at} 缺 instrument（= 数据包里的乐器名）`)\n    if (!lane.block) problems.push(`${at} 缺 block（载体方块）`)\n    if (lane.side !== 'N' && lane.side !== 'S') problems.push(`${at}.side 只能是 N 或 S`)\n    if (typeof lane.pos !== 'number' || lane.pos < 1) problems.push(`${at}.pos 必须是 ≥1 的整数`)\n    if (lane.window && lane.window.length !== 2) problems.push(`${at}.window 必须是两个数 [lo, hi]`)\n    const isDrum = !lane.window\n    if (isDrum && (!lane.keys || lane.keys.length === 0) && !lane.mirrorOf) {\n      problems.push(`${at} 没给 window（当打击乐轨处理）就必须给 keys（接受哪些 GM 鼓键）`)\n    }\n    return {\n      label: lane.label as string,\n      instrument: lane.instrument as string,\n      block: lane.block as string,\n      side: lane.side as 'N' | 'S',\n      pos: lane.pos as number,\n      window: lane.window ? ([lane.window[0], lane.window[1]] as [number, number]) : null,\n      sample: lane.sample,\n      tracks: lane.tracks ?? [],\n      keys: lane.keys,\n      keyBlocks: toKeyBlocks(lane.keyBlocks, at, problems),\n      tune: lane.tune,\n      thin: lane.thin,\n      mirrorOf: lane.mirrorOf,\n    }\n  })\n  if (problems.length > 0) throw new Error(`轨表有问题：\\n  - ${problems.join('\\n  - ')}`)\n  return lanes\n}\n\nfunction readJson(file: string): unknown {\n  if (!fs.existsSync(file)) throw new Error(`文件不存在：${file}`)\n  return JSON.parse(fs.readFileSync(file, 'utf8'))\n}\n\ninterface ProjectArgs {\n  projectFile?: string\n  songFile?: string\n  lanesFile?: string\n  lanes?: readonly RawLane[]\n  geometry?: RawGeometry\n}\n\n/** 组装工程：projectFile 给全量，songFile/lanesFile/lanes/geometry 逐项覆盖 */\nexport function loadProject(args: ProjectArgs): { project: BuildProject; geometry: Partial<GeometryOptions> } {\n  let song: SongPlan | undefined\n  let lanes: RawLane[] | undefined\n  let geometry: Partial<GeometryOptions> = {}\n  if (args.projectFile) {\n    const project = readJson(args.projectFile) as { song?: SongPlan; lanes?: RawLane[]; geometry?: RawGeometry }\n    song = project.song\n    lanes = project.lanes\n    geometry = { ...geometry, ...(project.geometry as Partial<GeometryOptions> | undefined) }\n  }\n  if (args.songFile) song = readJson(args.songFile) as SongPlan\n  if (args.lanesFile) lanes = readJson(args.lanesFile) as RawLane[]\n  if (args.lanes) lanes = [...args.lanes]\n  if (args.geometry) geometry = { ...geometry, ...(args.geometry as Partial<GeometryOptions>) }\n\n  if (!song) throw new Error('缺谱面：给 projectFile（含 song）或 songFile')\n  if (!lanes || lanes.length === 0) throw new Error('缺轨表：给 projectFile（含 lanes）、lanesFile 或 lanes')\n  if (!(song.bpm > 0)) throw new Error('谱面 bpm 非法')\n  if (!Array.isArray(song.notes) || song.notes.length === 0) throw new Error('谱面 notes 为空')\n  for (const [index, note] of song.notes.entries()) {\n    if (typeof note?.t !== 'number' || typeof note?.midi !== 'number' || typeof note?.track !== 'number') {\n      throw new Error(`notes[${index}] 必须是 { t, midi, track }（都是数字）`)\n    }\n  }\n  const normalized: SongPlan = {\n    bpm: song.bpm,\n    start: typeof song.start === 'number' ? song.start : 0,\n    notes: song.notes.map((note: SongNote) => ({ t: note.t, midi: note.midi, track: note.track })),\n  }\n  return { project: { song: normalized, lanes: toLanes(lanes), geometry }, geometry }\n}\n\nexport function registerBuildTool(ctx: Context, config: Config): void {\n  ctx.tools.register(\n    defineTool({\n      name: 'rm_build',\n      description:\n        '把红石音乐谱面编译成 Minecraft 数据包并（可选）部署开建。' +\n        '输入：谱面（bpm/start/notes[{t,midi,track}]）+ 轨表（每条轨 = 一种音色：instrument/block/side/pos/window/sample/tracks）。' +\n        '它会分配音符到槽位（每轨每刻最多 3 个音符盒）、算总线刷新中继器与各轨延迟补偿、' +\n        '生成 mcfunction 分片（每片 8000 条 + 片间 schedule 2t + 末尾唤醒中继器），' +\n        '并同时写出 Glissando 乐器定义（sound_event 强制用原版事件，杜绝\"全是错音\"）。' +\n        'action=pack 只写数据包；action=deploy 还会经 RCON 设 tick rate、reload、启用数据包、分段强加载并 /function 开建。' +\n        '★ 建造期间不要用别的脚本碰 RCON（会让建造任务失去连接并从头重跑）。',\n      parameters: {\n        action: { type: 'string', enum: ['pack', 'deploy'], description: 'pack=只生成数据包；deploy=再经 RCON 开建（默认 pack）' },\n        namespace: { type: 'string', description: '数据包命名空间（默认 rm_build，只能小写字母数字下划线）' },\n        projectFile: { type: 'string', description: '工程 JSON：{ song, lanes, geometry? }（与 songFile/lanes 二选一）' },\n        songFile: { type: 'string', description: '谱面 JSON：{ bpm, start, notes:[{t,midi,track}] }' },\n        lanesFile: { type: 'string', description: '轨表 JSON：[{label,instrument,block,side,pos,...}]' },\n        lanes: {\n          type: 'array',\n          description: '轨表（内联）',\n          items: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              label: { type: 'string', required: true, description: '轨的唯一标识' },\n              instrument: { type: 'string', required: true, description: '乐器名（进数据包乐器定义的文件名）' },\n              block: { type: 'string', required: true, description: '载体方块（红石导体 + 不在 mod 内置标签里）' },\n              side: { type: 'string', enum: ['N', 'S'], required: true, description: '走道北侧/南侧' },\n              pos: { type: 'number', required: true, description: '该侧第几条（1 起）：z = walkMid ∓ pos·laneGap，dy = 1+2(pos−1)' },\n              window: {\n                oneOf: [{ type: 'array', items: { type: 'number' } }, { type: 'null' }],\n                description: '音域窗口 [lo,hi]；null（或不给）= 打击乐轨',\n              },\n              sample: { type: 'number', description: '采样录音音高（缺省 = window[0]+12）；note = midi − sample + 12' },\n              tracks: { type: 'array', required: true, items: { type: 'number' }, description: '源轨号' },\n              keys: { type: 'array', items: { type: 'number' }, description: '打击乐：接受哪些 GM 鼓键' },\n              keyBlocks: { type: 'json', description: '打击乐：鼓键 → 载体方块（一条轨出多种鼓声）' },\n              tune: { type: 'number', description: '打击乐固定 note（默认 12 = 采样原始音高）' },\n              thin: { type: 'number', description: '抽稀：只保留 unit 为该值倍数的音（打击乐常用 2）' },\n              mirrorOf: { type: 'string', description: '镜像哪条轨（逐音复制，走道两侧同时发声）' },\n            },\n          },\n        },\n        geometry: {\n          type: 'object',\n          additionalProperties: false,\n          description: '几何（不给就用默认：originX=250 baseY=180 walkMid=520 laneGap=5 tailUnits=4）',\n          properties: {\n            originX: { type: 'number' },\n            baseY: { type: 'number' },\n            walkMid: { type: 'number' },\n            laneGap: { type: 'number' },\n            tailUnits: { type: 'number' },\n            busRefreshInterval: { type: 'number', description: '总线每铺多少格红石线插一个刷新中继器（默认 12）' },\n          },\n        },\n        outputDir: { type: 'string', description: '数据包目录；缺省 <serverDir>/<datapackDir>/<namespace>' },\n        packFormat: { type: 'number', description: 'pack_format（1.21 = 48，默认 48）' },\n        shardSize: { type: 'number', description: '每片 mcfunction 的命令数（默认 8000）' },\n        allowOccupiedBlocks: { type: 'boolean', description: '允许使用被 Glissando 内置标签圈走的方块（默认 false，会直接报错）' },\n        setTickRate: { type: 'boolean', description: 'deploy 时顺便设 tick rate（默认 true；它不存档，重启要重设）' },\n        doForceload: { type: 'boolean', description: 'deploy 时分段强加载建造范围（默认 true）' },\n      },\n      output: {\n        schema: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            action: { type: 'string', required: true },\n            namespace: { type: 'string', required: true },\n            datapackDir: { type: 'string', required: true },\n            unitSeconds: { type: 'number', required: true },\n            tickRate: { type: 'number', required: true },\n            units: { type: 'number', required: true },\n            commandCounts: {\n              type: 'object',\n              required: true,\n              additionalProperties: false,\n              properties: {\n                clears: { type: 'number', required: true },\n                fills: { type: 'number', required: true },\n                cells: { type: 'number', required: true },\n                commands: { type: 'number', required: true },\n                repeaters: { type: 'number', required: true },\n              },\n            },\n            shards: {\n              type: 'array',\n              required: true,\n              items: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                  name: { type: 'string', required: true },\n                  commands: { type: 'number', required: true },\n                },\n              },\n            },\n            files: {\n              type: 'array',\n              required: true,\n              items: {\n                type: 'object',\n                additionalProperties: false,\n                properties: { file: { type: 'string', required: true }, bytes: { type: 'number', required: true } },\n              },\n            },\n            instruments: {\n              type: 'array',\n              required: true,\n              items: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                  name: { type: 'string', required: true },\n                  block: { type: 'string', required: true },\n                  soundEvent: { type: 'string', required: true },\n                },\n              },\n            },\n            stats: {\n              type: 'object',\n              required: true,\n              additionalProperties: false,\n              properties: {\n                total: { type: 'number', required: true },\n                placed: { type: 'number', required: true },\n                dropped: { type: 'number', required: true },\n                outOfWindow: { type: 'number', required: true },\n                offGrid: { type: 'number', required: true },\n                thinned: { type: 'number', required: true },\n                capacity: { type: 'number', required: true },\n              },\n            },\n            lanes: {\n              type: 'array',\n              required: true,\n              items: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                  label: { type: 'string', required: true },\n                  instrument: { type: 'string', required: true },\n                  block: { type: 'string', required: true },\n                  z: { type: 'number', required: true },\n                  dy: { type: 'number', required: true },\n                  delay: { type: 'number', required: true },\n                  xStart: { type: 'number', required: true },\n                  notes: { type: 'number', required: true },\n                },\n              },\n            },\n            bounds: { type: 'json', required: true },\n            deploy: {\n              type: 'object',\n              required: true,\n              additionalProperties: false,\n              properties: {\n                requested: { type: 'boolean', required: true },\n                performed: { type: 'boolean', required: true },\n                steps: {\n                  type: 'array',\n                  required: true,\n                  items: {\n                    type: 'object',\n                    additionalProperties: false,\n                    properties: { command: { type: 'string', required: true }, result: { type: 'string', required: true } },\n                  },\n                },\n                forceload: { type: 'array', required: true, items: { type: 'string' } },\n                errors: { type: 'array', required: true, items: { type: 'string' } },\n              },\n            },\n            warnings: { type: 'array', required: true, items: { type: 'string' } },\n            nextSteps: { type: 'array', required: true, items: { type: 'string' } },\n          },\n        },\n        render: (_args, value) => {\n          const lines: string[] = []\n          lines.push(\n            `【${value.action}】${value.namespace} → ${value.datapackDir}\\n` +\n              `单位 ${(value.unitSeconds * 1000).toFixed(2)}ms（需要 tick rate ${value.tickRate.toFixed(3)}），共 ${value.units} 个单位\\n` +\n              `命令：清场 ${value.commandCounts.clears} / 铺底 ${value.commandCounts.fills} / 元件 ${value.commandCounts.cells} = 合计 ${value.commandCounts.commands} 条，切成 ${value.shards.length} 片\\n` +\n              `音符：放下 ${value.stats.placed}，丢弃 ${value.stats.dropped}（窗口外 ${value.stats.outOfWindow}、超容量 ${value.stats.capacity}、离网格 ${value.stats.offGrid}、抽稀 ${value.stats.thinned}）\\n` +\n              `乐器 ${value.instruments.length} 个（sound_event 全部为原版事件）`,\n          )\n          for (const lane of value.lanes) {\n            lines.push(`  z=${String(lane.z).padStart(4)} dy=${lane.dy} 延迟${lane.delay} 起点x=${lane.xStart}  ${lane.label}（${lane.instrument}）${lane.notes} 音`)\n          }\n          lines.push(`数据包文件 ${value.files.length} 个`)\n          for (const step of value.deploy.steps) lines.push(`  > ${step.command}\\n    ${step.result.split('\\n')[0]}`)\n          if (value.deploy.forceload.length > 0) lines.push(`强加载分段 ${value.deploy.forceload.length} 条：${value.deploy.forceload.join(' | ')}`)\n          if (value.deploy.errors.length > 0) lines.push(`✗ 部署报错：\\n  - ${value.deploy.errors.join('\\n  - ')}`)\n          if (value.warnings.length > 0) lines.push(`注意：\\n  - ${value.warnings.join('\\n  - ')}`)\n          lines.push(`下一步：\\n  - ${value.nextSteps.join('\\n  - ')}`)\n          return [{ type: 'text', text: lines.join('\\n') }]\n        },\n      },\n      async execute(args, exec) {\n        const namespace = args.namespace ?? 'rm_build'\n        const action = args.action ?? 'pack'\n        const { project, geometry } = loadProject(args)\n        const plan = planBuild(project, {\n          namespace,\n          packFormat: args.packFormat,\n          shardSize: args.shardSize,\n          allowOccupiedBlocks: args.allowOccupiedBlocks,\n        })\n        if (exec.signal.aborted) throw new Error('已取消')\n\n        if (!args.outputDir && config.serverDir.trim() === '') {\n          throw new Error(\n            '不知道数据包该写到哪：没给 outputDir，插件配置里的 serverDir 也是空的。' +\n              '二选一：调用时给 outputDir（例如 <服务端目录>/world/datapacks/rm_build），或在插件配置里设 serverDir。',\n          )\n        }\n        const datapackDir = args.outputDir ?? path.join(config.serverDir, config.datapackDir, namespace)\n        const written = writeDatapack({\n          dir: datapackDir,\n          namespace,\n          packFormat: args.packFormat ?? 48,\n          description: `rm_build: ${namespace}（${plan.units} 单位 / ${plan.allocation.stats.placed} 音）`,\n          shards: plan.shards,\n          extraShards: plan.refreshShards,\n          instruments: plan.instruments,\n          meta: plan.meta,\n        })\n\n        const forceload = forceloadCommands(forceloadSegments(plan.commands.bounds))\n        const warnings = [...plan.warnings]\n        const deploy = {\n          requested: action === 'deploy',\n          performed: false,\n          steps: [] as { command: string; result: string }[],\n          forceload,\n          errors: [] as string[],\n        }\n\n        if (action === 'deploy') {\n          if (!config.rconPassword) {\n            deploy.errors.push('没有配置 RCON 密码（插件配置 rconPassword）→ 只能 pack，不能 deploy')\n          } else {\n            const commands: string[] = []\n            if (args.setTickRate ?? true) commands.push(`tick rate ${Number(plan.tickRate.toFixed(4))}`)\n            commands.push('reload')\n            commands.push(`datapack enable \"file/${namespace}\"`)\n            if (args.doForceload ?? true) commands.push(...forceload)\n            commands.push(`function ${namespace}:build1`)\n            commands.push('datapack list')\n            let client\n            try {\n              client = await openRcon({\n                host: config.rconHost,\n                port: config.rconPort,\n                password: config.rconPassword,\n              })\n              const results = await client.execMany(commands, { batchDelayMs: 60 })\n              results.forEach((result, index) => deploy.steps.push({ command: commands[index] as string, result: result.trim() }))\n              deploy.performed = true\n              const listResult = deploy.steps[deploy.steps.length - 1]\n              if (listResult && !/file\\/|available|enabled/i.test(listResult.result)) {\n                warnings.push(`datapack list 的输出看起来不含 \"${namespace}\"：${listResult.result.slice(0, 200)}`)\n              }\n            } catch (error) {\n              deploy.errors.push(String(error instanceof Error ? error.message : error))\n            } finally {\n              client?.close()\n            }\n          }\n        }\n\n        const meta = plan.meta as { lanes?: { notes?: number }[] }\n        const nextSteps = [\n          `数据包已写到 ${datapackDir}；若服务端没在跑或目录不在这，把整个目录拷进 <serverDir>/<datapackDir>/ 再 /reload。`,\n          `/reload → /datapack enable \"file/${namespace}\" → /function ${namespace}:build1（分片会自动 schedule 接力，最后唤醒中继器）。`,\n          `建完用标签断言复核音色无歧义：/execute if block <x> <y> <z> #${namespace}:note_block_instruments/<乐器> 必须 passed。`,\n          '看服务端启动日志有没有 Errors in registry / Failed to get element —— 有就是乐器表没配好（会回退 harp，全是错音）。',\n          `/tick query 看平均刻时间；平均 >40ms 就先 kill @e[type=!player] 并减少灯/粒子。`,\n        ]\n        if (plan.tickRate > 20.5 || plan.tickRate < 19.5) {\n          nextSteps.push(`★ tick rate 设成 ${plan.tickRate.toFixed(3)}（不存档，服务端每次重启都要重设），否则速度不对。`)\n        }\n        nextSteps.push('建造期间只用读日志看进度，不要用别的脚本碰 RCON（会让建造任务失去连接并从头重跑）。')\n\n        return {\n          action,\n          namespace,\n          datapackDir,\n          unitSeconds: Number(plan.unitSeconds.toFixed(6)),\n          tickRate: Number(plan.tickRate.toFixed(4)),\n          units: plan.units,\n          commandCounts: {\n            clears: plan.commands.counts.clears,\n            fills: plan.commands.counts.fills,\n            cells: plan.commands.counts.cells,\n            commands: plan.commands.counts.commands,\n            repeaters: plan.commands.repeaterCommands.length,\n          },\n          shards: plan.shards.map((shard) => ({ name: shard.name, commands: shard.lines.length })),\n          files: written.files.map((file) => ({ file: file.file, bytes: file.bytes })),\n          instruments: plan.instruments.map((instrument) => ({\n            name: instrument.name,\n            block: instrument.block,\n            soundEvent: instrument.soundEvent,\n          })),\n          stats: {\n            total: plan.allocation.stats.total,\n            placed: plan.allocation.stats.placed,\n            dropped: plan.allocation.stats.dropped,\n            outOfWindow: plan.allocation.stats.outOfWindow,\n            offGrid: plan.allocation.stats.offGrid,\n            thinned: plan.allocation.stats.thinned,\n            capacity: plan.allocation.stats.capacity,\n          },\n          lanes: plan.layout.lanes.map((lane, index) => ({\n            label: lane.label,\n            instrument: lane.instrument,\n            block: lane.block,\n            z: lane.z,\n            dy: lane.dy,\n            delay: lane.delay,\n            xStart: lane.xStart,\n            notes: meta.lanes?.[index]?.notes ?? 0,\n          })),\n          bounds: plan.commands.bounds,\n          deploy,\n          warnings,\n          nextSteps,\n        }\n      },\n    }),\n  )\n}\n\nexport { DEFAULT_GEOMETRY }\n"
    },
    {
      "path": "src/tool-render.ts",
      "content": "/**\n * tool-render.ts —— rm_render：渲染乐器采样 → 统一起音对齐 → 自验证\n *\n * 对应 PIPELINE 第 4 步。两种模式：\n *   render —— 从 .sf2（SoundFont）渲染，需要可选依赖 js-synthesizer\n *   align  —— 只对齐 sourceDir 里已有的 wav（没装 fluidsynth 时也能用）\n */\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Config } from './config'\nimport {\n  createFluidSynthRenderer,\n  readInstrumentsManifest,\n  renderSamples,\n  type InstrumentSlot,\n  type SlotKind,\n} from './music/sample-render'\n\ninterface RawSlot {\n  name?: string\n  kind?: string\n  block?: string\n  program?: number\n  window?: number[]\n  sample?: number\n  key?: number\n  durationSec?: number\n  decaySec?: number\n  level?: number\n}\n\n/** 把工具入参（宽松 JSON）收敛成严格的槽定义，顺便给出可读的报错 */\nexport function toSlots(raw: readonly RawSlot[]): InstrumentSlot[] {\n  const problems: string[] = []\n  const slots = raw.map((slot, index) => {\n    const kind = (slot.kind ?? 'pitched') as SlotKind\n    if (kind !== 'pitched' && kind !== 'drum') problems.push(`slots[${index}].kind 只能是 pitched 或 drum`)\n    if (!slot.name) problems.push(`slots[${index}] 缺 name`)\n    if (!slot.block) problems.push(`slots[${index}] 缺 block`)\n    if (slot.window && slot.window.length !== 2) problems.push(`slots[${index}].window 必须是两个数 [lo, hi]`)\n    if (kind === 'pitched' && typeof slot.program !== 'number') problems.push(`slots[${index}] 是有音高乐器，必须给 program`)\n    if (kind === 'drum' && typeof slot.key !== 'number') problems.push(`slots[${index}] 是打击乐，必须给 key`)\n    return {\n      name: slot.name as string,\n      kind,\n      block: slot.block as string,\n      program: slot.program,\n      window: slot.window ? ([slot.window[0], slot.window[1]] as [number, number]) : undefined,\n      sample: slot.sample,\n      key: slot.key,\n      durationSec: slot.durationSec,\n      decaySec: slot.decaySec,\n      level: slot.level,\n    }\n  })\n  if (problems.length > 0) throw new Error(`槽表有问题：\\n  - ${problems.join('\\n  - ')}`)\n  return slots\n}\n\nexport function registerRenderTool(ctx: Context, config: Config): void {\n  ctx.tools.register(\n    defineTool({\n      name: 'rm_render',\n      description:\n        '渲染红石音乐用的乐器采样并做【统一起音对齐】。' +\n        '规则一律是\"5ms 滑动 RMS 首次达到最大值 50% 处裁切 + 2ms 淡入 + 指数衰减\"，' +\n        '渲完立刻读回来重量一次起音并断言 ≤ maxOnsetMs —— 分层齐奏时各层起音差 >5ms 就会被听成\"错拍\"。' +\n        'action=render 从 .sf2 渲染（需 js-synthesizer）；action=align 只对齐 sourceDir 里已有的 wav。' +\n        '产出 <outDir>/<name>.wav 与 <outDir>/instruments.json 清单（含每个采样的录音音高 sample，供 rm_build 算 note 值）。',\n      parameters: {\n        outDir: { type: 'string', required: true, description: '采样输出目录（还要放 instruments.json）' },\n        action: { type: 'string', enum: ['render', 'align'], description: 'render=从 sf2 渲染；align=只对齐已有 wav（默认 render）' },\n        slots: {\n          type: 'array',\n          description: '乐器槽表：一个槽 = 一种音色（name/kind/block，有音高给 program+window+sample，打击乐给 key）',\n          items: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              name: { type: 'string', required: true, description: '槽名（进文件名，只能字母数字下划线）' },\n              kind: { type: 'string', enum: ['pitched', 'drum'], required: true },\n              block: { type: 'string', required: true, description: '载体方块（红石导体，且不能落在 mod 内置标签里）' },\n              program: { type: 'number', description: 'GM 音色号（0-based）' },\n              window: { type: 'array', items: { type: 'number' }, description: '音域窗口 [lo, hi]（MIDI 音高）' },\n              sample: { type: 'number', description: '★ 采样录音音高（缺省 = window[0]+12）；必须显式记录，note = midi − sample + 12' },\n              key: { type: 'number', description: 'GM 鼓键（打击乐）' },\n              durationSec: { type: 'number', description: '渲染时长（秒；有音高默认 1.3，打击乐 0.6）' },\n              decaySec: { type: 'number', description: '指数衰减时间常数（秒；有音高默认 0.5，打击乐 0.3）' },\n              level: { type: 'number', description: '归一化电平（默认 0.92）' },\n            },\n          },\n        },\n        slotsFile: { type: 'string', description: '槽表 JSON 文件路径（与 slots 二选一）' },\n        sourceDir: { type: 'string', description: 'align 模式：放着 <name>.wav 的目录' },\n        soundFont: { type: 'string', description: 'SoundFont (.sf2) 路径；缺省用插件配置 soundFont' },\n        namespace: { type: 'string', description: '采样命名空间（写进清单的 sound 字段，默认 rm）' },\n        sampleRate: { type: 'number', description: '采样率 Hz（默认用插件配置 sampleRate）' },\n        maxOnsetMs: { type: 'number', description: '允许的最大输出起音 ms（默认用插件配置 maxOnsetMs=3）' },\n      },\n      output: {\n        schema: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            mode: { type: 'string', required: true },\n            outDir: { type: 'string', required: true },\n            sampleRate: { type: 'number', required: true },\n            maxOnsetMs: { type: 'number', required: true },\n            count: { type: 'number', required: true },\n            ok: { type: 'number', required: true },\n            failed: { type: 'number', required: true },\n            manifestFile: { type: 'string', required: true },\n            totalKB: { type: 'number', required: true },\n            items: {\n              type: 'array',\n              required: true,\n              items: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                  name: { type: 'string', required: true },\n                  kind: { type: 'string', required: true },\n                  sound: { type: 'string', required: true },\n                  block: { type: 'string', required: true },\n                  sample: { type: 'number', required: true },\n                  window: { type: 'json', required: true },\n                  key: { type: 'json', required: true },\n                  file: { type: 'string', required: true },\n                  sizeKB: { type: 'number', required: true },\n                  durationSec: { type: 'number', required: true },\n                  rawOnsetMs: { type: 'number', required: true },\n                  cutMs: { type: 'number', required: true },\n                  outOnsetMs: { type: 'number', required: true },\n                  ok: { type: 'boolean', required: true },\n                },\n              },\n            },\n            warnings: { type: 'array', required: true, items: { type: 'string' } },\n          },\n        },\n        render: (_args, value) => {\n          const lines = value.items.map(\n            (item) =>\n              `  ${item.name.padEnd(14)} 起音 ${item.rawOnsetMs.toFixed(1).padStart(7)}ms → 裁 ${item.cutMs\n                .toFixed(1)\n                .padStart(6)}ms → 输出 ${item.outOnsetMs.toFixed(2).padStart(6)}ms  ${item.ok ? '✓' : '✗ 不合格'}  ${item.sound}  ${item.sizeKB}KB`,\n          )\n          const head =\n            `【${value.mode}】${value.count} 个采样（合格 ${value.ok} / 不合格 ${value.failed}），${value.sampleRate}Hz，最大允许起音 ${value.maxOnsetMs}ms\\n` +\n            `输出目录：${value.outDir}\\n清单：${value.manifestFile}\\n共 ${value.totalKB.toFixed(0)} KB`\n          const warning = value.warnings.length > 0 ? `\\n注意：\\n  - ${value.warnings.join('\\n  - ')}` : ''\n          return [{ type: 'text', text: `${head}\\n\\n${lines.join('\\n')}${warning}` }]\n        },\n      },\n      async execute(args, exec) {\n        const sampleRate = args.sampleRate ?? config.sampleRate\n        const maxOnsetMs = args.maxOnsetMs ?? config.maxOnsetMs\n        const namespace = args.namespace ?? 'rm'\n        const mode = args.action ?? 'render'\n\n        let slots: InstrumentSlot[]\n        if (args.slotsFile) {\n          const parsed = JSON.parse(fs.readFileSync(args.slotsFile, 'utf8')) as { slots?: RawSlot[] } | RawSlot[]\n          const list = Array.isArray(parsed) ? parsed : (parsed.slots ?? [])\n          slots = toSlots(list)\n        } else if (args.slots) {\n          slots = toSlots(args.slots as RawSlot[])\n        } else if (args.sourceDir) {\n          // 没给槽表就退回清单里的 items（instruments.json 本身就是可再用作槽表）\n          const manifest = readInstrumentsManifest(path.join(args.sourceDir, 'instruments.json'))\n          slots = manifest.items.map((item) => ({\n            name: item.name,\n            kind: item.kind,\n            block: item.block,\n            program: undefined,\n            window: item.window ?? undefined,\n            sample: item.sample,\n            key: item.key ?? undefined,\n          }))\n        } else {\n          throw new Error('必须给 slots / slotsFile，或给 sourceDir（用其 instruments.json 当槽表）')\n        }\n\n        const warnings: string[] = []\n        const outDir = args.outDir\n        let renderer\n        if (mode === 'render') {\n          const soundFont = args.soundFont ?? config.soundFont\n          if (soundFont.trim() === '') {\n            throw new Error(\n              'render 模式需要 SoundFont：调用时给 soundFont（.sf2 路径），或在插件配置里设 soundFont。' +\n                '手上只有渲好的 wav 就用 action=\"align\"（配 sourceDir），它不需要 SoundFont。',\n            )\n          }\n          renderer = await createFluidSynthRenderer(soundFont, sampleRate)\n        }\n        if (exec.signal.aborted) throw new Error('已取消')\n\n        const outcome = renderSamples({\n          slots,\n          outDir,\n          sampleRate,\n          maxOnsetMs,\n          namespace,\n          sourceDir: args.sourceDir,\n          renderer,\n        })\n        renderer?.dispose()\n\n        const failed = outcome.items.filter((item) => !item.ok)\n        if (failed.length > 0) {\n          warnings.push(\n            `有 ${failed.length} 个采样起音 >${maxOnsetMs}ms（${failed.map((f) => `${f.name}=${f.outOnsetMs}ms`).join('、')}）：` +\n              '这会让该层听起来\"晚半拍\"。检查是否用了起音很慢的音色（如 GM44 Tremolo Strings），或把裁切上限调小。',\n          )\n        }\n\n        return {\n          mode,\n          outDir,\n          sampleRate,\n          maxOnsetMs,\n          count: outcome.items.length,\n          ok: outcome.ok,\n          failed: outcome.failed,\n          manifestFile: outcome.manifestFile,\n          totalKB: Number(outcome.items.reduce((sum, item) => sum + item.sizeKB, 0).toFixed(1)),\n          items: outcome.items.map((item) => ({\n            name: item.name,\n            kind: item.kind,\n            sound: item.sound,\n            block: item.block,\n            sample: item.sample,\n            window: item.window,\n            key: item.key,\n            file: item.file,\n            sizeKB: item.sizeKB,\n            durationSec: item.durationSec,\n            rawOnsetMs: item.rawOnsetMs,\n            cutMs: item.cutMs,\n            outOnsetMs: item.outOnsetMs,\n            ok: item.ok,\n          })),\n          warnings,\n        }\n      },\n    }),\n  )\n}\n"
    },
    {
      "path": "src/music/rcon.ts",
      "content": "/**\n * rcon.ts —— 极简 Minecraft RCON 客户端（Source RCON 协议）\n *\n * 为什么自己写：build/deploy 必须在同一个进程里【串行】发命令。\n * 并行发 RCON 会互相抢锁，实战里正因如此让建造任务失去连接、进度从 1575 退回 257 并从头重跑。\n * 这里用一个串行队列保证同一时刻只有一条命令在飞。\n */\nimport net from 'node:net'\n\nconst TYPE_AUTH = 3\nconst TYPE_COMMAND = 2\n\nexport interface RconOptions {\n  host: string\n  port: number\n  password: string\n  /** 单条命令超时（毫秒），默认 15s */\n  timeoutMs?: number\n}\n\nexport interface RconClient {\n  exec(command: string): Promise<string>\n  execMany(\n    commands: readonly string[],\n    options?: { batchDelayMs?: number; onProgress?: (done: number, total: number) => void },\n  ): Promise<string[]>\n  close(): void\n}\n\nfunction encodePacket(id: number, type: number, body: string): Buffer {\n  const payload = Buffer.from(body, 'utf8')\n  const buf = Buffer.alloc(14 + payload.length)\n  buf.writeInt32LE(10 + payload.length, 0)\n  buf.writeInt32LE(id, 4)\n  buf.writeInt32LE(type, 8)\n  payload.copy(buf, 12)\n  buf.writeInt8(0, 12 + payload.length)\n  buf.writeInt8(0, 13 + payload.length)\n  return buf\n}\n\n/** 从缓冲区头部取一条完整包；不完整返回 null */\nexport function decodePacket(buffer: Buffer): { id: number; type: number; body: string; size: number } | null {\n  if (buffer.length < 12) return null\n  const length = buffer.readInt32LE(0)\n  if (length < 10 || buffer.length < length + 4) return null\n  const id = buffer.readInt32LE(4)\n  const type = buffer.readInt32LE(8)\n  const body = buffer.toString('utf8', 12, length + 2)\n  return { id, type, body, size: length + 4 }\n}\n\nexport async function openRcon(options: RconOptions): Promise<RconClient> {\n  const timeoutMs = options.timeoutMs ?? 15_000\n  const socket = await new Promise<net.Socket>((resolve, reject) => {\n    const s = net.createConnection({ host: options.host, port: options.port })\n    const timer = setTimeout(() => {\n      s.destroy()\n      reject(new Error(`连接 RCON ${options.host}:${options.port} 超时`))\n    }, 8000)\n    s.once('connect', () => {\n      clearTimeout(timer)\n      resolve(s)\n    })\n    s.once('error', (error) => {\n      clearTimeout(timer)\n      reject(new Error(`连接 RCON 失败：${error.message}`))\n    })\n  })\n\n  // ── 第一步：登录（认证必须在挂上通用分发器之前完成，避免两个 data 监听器争抢缓冲区）\n  await new Promise<void>((resolve, reject) => {\n    let buf = Buffer.alloc(0)\n    const fail = (error: Error): void => {\n      cleanup()\n      // 认证失败/超时后必须主动断开，否则连接会挂着不释放\n      socket.destroy()\n      reject(error)\n    }\n    const timer = setTimeout(() => fail(new Error('RCON 登录超时')), 8000)\n    const cleanup = (): void => {\n      clearTimeout(timer)\n      socket.off('data', onData)\n      socket.off('error', onError)\n    }\n    const onData = (chunk: Buffer): void => {\n      buf = Buffer.concat([buf, chunk])\n      const packet = decodePacket(buf)\n      if (!packet) return\n      cleanup()\n      if (packet.id === -1) fail(new Error('RCON 认证失败（密码不对）'))\n      else resolve()\n    }\n    const onError = (error: Error): void => {\n      fail(new Error(`RCON 登录时连接出错：${error.message}`))\n    }\n    socket.on('data', onData)\n    socket.on('error', onError)\n    socket.write(encodePacket(1, TYPE_AUTH, options.password))\n  })\n\n  // ── 第二步：通用分发（串行队列 + 单条超时）\n  let buffer = Buffer.alloc(0)\n  let pending: { id: number; resolve: (v: string) => void; reject: (e: Error) => void; timer: NodeJS.Timeout } | undefined\n  let nextId = 2\n  let failure: Error | undefined\n  const waiters: (() => void)[] = []\n\n  const settle = (error: Error | undefined, value?: string): void => {\n    const current = pending\n    pending = undefined\n    const next = waiters.shift()\n    if (current) {\n      clearTimeout(current.timer)\n      if (error) current.reject(error)\n      else current.resolve(value ?? '')\n    }\n    if (next) next()\n  }\n\n  socket.on('data', (chunk) => {\n    buffer = Buffer.concat([buffer, chunk])\n    for (;;) {\n      const packet = decodePacket(buffer)\n      if (!packet) break\n      buffer = Buffer.from(buffer.subarray(packet.size))\n      if (pending && packet.id === pending.id) settle(undefined, packet.body)\n    }\n  })\n  socket.on('error', (error) => {\n    failure = new Error(`RCON 连接出错：${error.message}`)\n    settle(failure)\n    for (const resume of waiters.splice(0)) resume()\n  })\n  socket.on('close', () => {\n    if (pending) settle(failure ?? new Error('RCON 连接被关闭'))\n  })\n\n  const send = (command: string, timeout: number): Promise<string> =>\n    new Promise<string>((resolve, reject) => {\n      const run = (): void => {\n        if (failure) {\n          reject(failure)\n          const next = waiters.shift()\n          if (next) next()\n          return\n        }\n        const id = nextId++\n        pending = {\n          id,\n          resolve,\n          reject,\n          timer: setTimeout(() => settle(new Error(`RCON 命令超时：${command}`)), timeout),\n        }\n        socket.write(encodePacket(id, TYPE_COMMAND, command))\n      }\n      if (pending) waiters.push(run)\n      else run()\n    })\n\n  return {\n    exec: (command) => send(command, timeoutMs),\n    async execMany(commands, runOptions) {\n      const results: string[] = []\n      let done = 0\n      for (const command of commands) {\n        results.push(await send(command, 60_000))\n        done++\n        runOptions?.onProgress?.(done, commands.length)\n        if (runOptions?.batchDelayMs) await new Promise((r) => setTimeout(r, runOptions.batchDelayMs))\n      }\n      return results\n    },\n    close() {\n      socket.end()\n      socket.destroy()\n    },\n  }\n}\n"
    }
  ],
